import {refreshEdgePanel,panelEdgeRecipe} from './edge-panels.js';
import {refreshGarmentSurfaces} from './garment-surfaces.js';
import {ensureEdges} from './edges.js';
import {resolvePanelCut,followBoundaryAnchors,nearestBoundary,GEOMETRY_EPSILON} from './panel-cut.js';
import {linkDerivedMirrors} from './mirror-service.js';
import {appendObjects} from './document-store.js';
import {geometryMirror} from './symmetry.js';
import {uid,clone,I,mul,inverse,worldPath,bounds,point} from './core.js';
const cache=new Map();let evaluations=0;
export const panelStats=()=>({evaluations});
export function panelCandidates(os,line,ids=[],options={}){const explicit=os.filter(o=>ids.includes(o.id)&&o.closed&&!o.panelOf);return (explicit.length?explicit:os.filter(o=>o.type==='path'&&o.closed&&!o.panelOf&&!o.hidden)).filter(o=>resolvePanelCut(o,line,options.snapTolerance??GEOMETRY_EPSILON,options).valid);}
function generate(base,cuts){const signature=JSON.stringify([worldPath({...base,modifiers:(base.modifiers||[]).filter(m=>['bend','fabricFall'].includes(m.type))}).nodes,base.subpaths,base.closed,base.matrix,cuts.map(c=>[c.nodes,c.matrix,c.closed])]);if(cache.has(signature))return clone(cache.get(signature));evaluations++;let regions=[{...clone(base),id:uid(),regionKey:''}];for(let j=0;j<cuts.length;j++){const next=[];for(const r of regions){const resolution=resolvePanelCut(r,cuts[j]);if(!resolution.valid){next.push(r);continue;}const parts=resolution.regions.sort((a,b)=>{const x=bounds(a),y=bounds(b),inv=inverse(base.matrix),p=point(inv,{x:x.x+x.w/2,y:x.y+x.h/2}),q=point(inv,{x:y.x+y.w/2,y:y.y+y.h/2});return Math.abs(p.y-q.y)>.01?p.y-q.y:p.x-q.x;});parts.forEach((p,i)=>{p.regionKey=r.regionKey+j+':'+i+';';next.push(p);});}regions=next;}if(regions.length<2)throw Error('Esta línea no divide la pieza seleccionada. Debe entrar y salir del contorno.');const boxes=regions.map(r=>bounds(r)),vertical=regions.length===2&&Math.abs(boxes[0].x+boxes[0].w/2-boxes[1].x-boxes[1].w/2)>Math.abs(boxes[0].y+boxes[0].h/2-boxes[1].y-boxes[1].h/2);regions.forEach((r,i)=>{r.name=regions.length===2?(vertical?(i===0?'Panel izquierdo':'Panel derecho'):(i===0?'Panel superior':'Panel inferior')):'Panel '+(i+1);r.stroke='none';r.width=0;r.modifiers=[];r.symmetryExcluded=true;r.mirrorPolicy='custom';delete r.instanceOf;r.semanticType='region';delete r.symmetry;delete r.mirrorPeer;delete r.structureKey;delete r.panelCuts;delete r.regionIds;delete r.surfaceBoundaryIds;delete r.surfaceInvalid;r.matrix=I();});if(cache.size>100)cache.clear();cache.set(signature,clone(regions));return regions;}
export function previewPanels(base,line,os,options={}){const resolution=resolvePanelCut(base,line,options.snapTolerance??GEOMETRY_EPSILON,options);if(!resolution.valid)throw Error(resolution.diagnostics.message);return generate(base,[...(base.panelCuts||[]).filter(id=>id!==line.id).map(id=>os.find(o=>o.id===id)).filter(Boolean),resolution.snappedPath]);}
export function createPanels(os,base,line,options={}){ensureEdges(base);ensureEdges(line);previewPanels(base,line,os,options);const resolution=resolvePanelCut(base,line,options.snapTolerance??GEOMETRY_EPSILON,options);Object.assign(line,resolution.snappedPath);base.panelCuts??=[];if(!base.panelCuts.includes(line.id))base.panelCuts.push(line.id);line.panelOf=base.id;line.semanticType='panelBoundary';line.name='División '+base.panelCuts.length;line.category=base.category;line.panelAnchor=mul(inverse(base.matrix),line.matrix);line.clip=base.id;line.symmetryExcluded=true;line.mirrorPolicy='custom';if(base.symmetry)geometryMirror(line,base.symmetry.axis);line.symmetryScope={mode:base.symmetry?'full':'owned',axisRef:'document-center'};refreshPanels(os);return os.filter(o=>o.panelOf===base.id&&o.semanticType==='region');}
export function refreshPanels(os){refreshGarmentSurfaces(os);for(const base of os.filter(o=>!o.surfaceInvalid&&(o.panelCuts?.length||o.regionIds?.length))){const cuts=(base.panelCuts||[]).map(id=>os.find(o=>o.id===id)).filter(Boolean);base.panelCuts=cuts.map(o=>o.id);const edgeRegions=os.filter(o=>o.panelOf===base.id&&o.semanticType==='region'&&(o.panelEdgeSelection||o.panelEdgeDerived));for(const r of edgeRegions)if(!r.instanceOf)refreshEdgePanel(r,base,os);const previous=os.filter(o=>o.panelOf===base.id&&o.semanticType==='region'&&!o.panelEdgeSelection&&!o.panelEdgeDerived);if(!cuts.length){for(const r of previous){for(const graphic of os.filter(o=>o.clip===r.id))graphic.clip=base.id;os.splice(os.indexOf(r),1);}if(edgeRegions.length)base.regionIds=edgeRegions.map(r=>r.id);else delete base.regionIds;delete base.panelCuts;continue;}for(const c of cuts){if(c.panelAnchor)c.matrix=mul(base.matrix,c.panelAnchor);followBoundaryAnchors(base,c);}let generated;try{generated=generate(base,cuts);}catch{continue;}const ids=[];for(const r of generated){const old=previous.find(p=>p.regionKey===r.regionKey),id=old?.id||uid(),appearance=old?{fill:old.fill,opacity:old.opacity,name:old.name,material:old.material,graphics:old.graphics,fabricTexture:old.fabricTexture?clone(old.fabricTexture):undefined}: {fill:base.fill,opacity:1,material:null,graphics:[]};const data={...r,...appearance,mirrorPolicy:old?.mirrorPolicy||'custom',id,panelOf:base.id,group:base.group,category:base.category};if(old)Object.assign(old,data);else appendObjects(os,[data]);ids.push(id);}for(const old of previous)if(!ids.includes(old.id)){for(const graphic of os.filter(o=>o.clip===old.id))graphic.clip=base.id;os.splice(os.indexOf(old),1);}base.regionIds=[...ids,...edgeRegions.map(r=>r.id)];}}
export function editPanelAnchor(os,o){if(o?.semanticType!=='panelBoundary')return;const base=os.find(p=>p.id===o.panelOf);if(!base)return;o.panelAnchor=mul(inverse(base.matrix),o.matrix);const resolution=resolvePanelCut(base,o);if(resolution.valid)Object.assign(o,resolution.snappedPath);else if(o.boundaryAnchors)o.boundaryAnchors=o.boundaryAnchors.filter(a=>{const n=o.nodes[a.endpoint==='start'?0:o.nodes.length-1],near=nearestBoundary(base,point(o.matrix,n));if(near.distance>GEOMETRY_EPSILON)return false;Object.assign(a,{boundarySegmentId:near.boundarySegmentId,boundaryPosition:near.boundaryPosition,boundarySubpath:near.boundarySubpath});return true;});}
export function panelBoundary(os,region){const base=os.find(o=>o.id===region.panelOf);return os.find(o=>o.id===(region.panelEdgeSelection?.required.find(r=>r.source!==base?.id)?.source||base?.panelCuts?.[0]));}

// Ownership evaluation includes linked divisions within a centered parent.
export function resolvePanelMirrors(p,view){if(!p.liveMirror)return;const os=p.views[view];for(const base of os.filter(o=>o.panelCuts?.length)){for(const id of [...base.panelCuts]){const cut=os.find(o=>o.id===id),peer=os.find(o=>o.id===cut?.mirrorPeer);if(peer?.panelOf===base.id&&!base.panelCuts.includes(peer.id))base.panelCuts.push(peer.id);}}refreshPanels(os);for(const base of os.filter(o=>o.panelCuts?.length))linkDerivedMirrors(p,view,base,os.filter(o=>o.panelOf===base.id&&o.semanticType==='region'));}

export function migratePanelAnchors(p){for(const os of Object.values(p.views))for(const cut of os.filter(o=>o.semanticType==='panelBoundary'&&o.panelOf&&!o.boundaryAnchors)){const base=os.find(o=>o.id===cut.panelOf);if(!base)continue;const r=resolvePanelCut(base,cut);if(r.valid)Object.assign(cut,r.snappedPath);}}

// The same normal region record, appearance and owner relation as drawn panels.
// Independent source paths and their effects are never converted into divisions.
export function createPanelFromEdges(p,view,base,candidate){
 if(!candidate?.path?.closed)throw Error('Elegí una región para crear el panel.');
 const os=p.views[view],region={...clone(candidate.path),id:uid(),name:'Panel '+(os.filter(o=>o.panelOf===base.id&&o.semanticType==='region').length+1),panelOf:base.id,semanticType:'region',category:base.category,group:base.group,fill:base.fill==='none'?'#ffffff':base.fill||'#ffffff',stroke:'none',width:0,opacity:1,modifiers:[],symmetryExcluded:true,mirrorPolicy:'custom',panelEdgeSelection:panelEdgeRecipe(candidate)};
 delete region.regionSources;
 appendObjects(os,[region]);base.regionIds??=[];base.regionIds.push(region.id);
 // Centered garment panels use the existing linked-instance projection. An
 // owned mirrored garment gets its panel through materializeInstances as usual.
 const axis=p.centerAxis??350,b=bounds(region),centered=base.symmetry||base.mirrorPolicy==='centered';
 if(p.liveMirror&&centered&&(b.x+b.w<=axis+.001&&b.x<axis-.5||b.x>=axis-.001&&b.x+b.w>axis+.5)){
  const peer={...clone(region),id:uid(),name:region.name+' · espejo',instanceOf:region.id,mirrorPeer:region.id,mirrorPolicy:'linked',mirrorAxisRef:'document-center',matrix:mul([-1,0,0,1,2*axis,0],region.matrix)};
  delete peer.panelEdgeSelection;peer.panelEdgeDerived=true;region.mirrorPeer=peer.id;region.mirrorPolicy='linked';region.mirrorAxisRef='document-center';appendObjects(os,[peer]);base.regionIds.push(peer.id);
 }
 return region;
}
